example.programlisting:
...
lookup("location");
switch ($retcode) {
    case -1:
    case -3:
        sl_send_reply("404", "Not Found");
        exit;
    case -2:
        sl_send_reply("405", "Not Found");
        exit;
};
...

...
assign_server("ORIG_SAA", "location", "orig", 0);
...
route[ORIG_SAA] {
    if($avp(saa_return_code) != 1) {
        t_reply("504", "Server Time-out");
        exit;
    }
    # continue as for a registered user
}
...

...
impu_registered("location");
switch ($retcode) {
    case -1:
        sl_send_reply("404", "Not Found");
        exit;
    case 1:
        #true, continue with normal processing
};
...

...
term_impu_registered("location");
switch ($retcode) {
     case -1:
          sl_send_reply("404", "Not Found");
          exit;
     case 1:
          #true, continue with normal processing
};
...
